const tablet = tabletsAutorizados.find(t =>
  t.device_id === body.device_id &&
  t.status === 'ativo'
) || null;

if (exigeDispositivoAutorizado && !tablet) {
  erros.push('Dispositivo não autorizado para este usuário de garagem.');
}

if (tablet && tablet.unidade !== 'Livre' && body.unidade && tablet.unidade !== body.unidade) {
  erros.push(
