const body = $json.body || $json;

const TOKEN_APP = 'cmw_chk_2026_9Kf3XwP2mQa8LdR7VnT4HsYc';

const erros = [];

if (!body.token_app || body.token_app !== TOKEN_APP) {
  erros.push('Token do aplicativo inválido.');
}

if (!body.matricula) {
  erros.push('Matrícula obrigatória.');
}

if (!body.pin) {
  erros.push('PIN obrigatório.');
}

if (!body.device_id) {
  erros.push('device_id obrigatório.');
}

if (erros.length > 0) {
  return [{
    json: {
      autorizado: false,
      parar_fluxo: true,
      status_code: 400,
      erros
    }
  }];
}

return [{
  json: {
    autorizado: null,
    parar_fluxo: false,
    token_app: body.token_app,
    matricula: String(body.matricula).trim(),
    pin: String(body.pin).trim(),
    device_id: body.device_id
  }
}];

const crypto = require('crypto');

const input = $('Preparar Validação Motorista').first().json;


const dispositivosAutorizados = [
  { device_id: 'TABLET-OPERACAO-01', nome_dispositivo: 'Tablet Operação 01', unidade: 'Extrema', status: 'ativo' },
  { device_id: 'TABLET-OPERACAO-02', nome_dispositivo: 'Tablet Operação 02', unidade: 'Bragança', status: 'ativo' },
  { device_id: 'DEVICE-7ebf93be-3a63-4ce0-ba52-7b5f4dd80a01', nome_dispositivo: 'Mac João - Teste', unidade: 'Livre', status: 'ativo' }
];

// O node Directus com Get Many Raw retorna 1 item por item encontrado.
// Com alwaysOutputData=true, se não encontrar pode retornar objeto vazio.
const motorista = $json && $json.id ? $json : null;

if (!motorista) {
  return [{
    json: {
      autorizado: false,
      status_code: 404,
      erro: 'Motorista não encontrado.'
    }
  }];
}

if (motorista.status !== 'ativo') {
  return [{
    json: {
      autorizado: false,
      status_code: 403,
      erro: 'Motorista inativo.'
    }
  }];
}

const PIN_PEPPER = 'cmw_pin_pepper_2026';
const base = `${input.matricula}:${input.pin}:${PIN_PEPPER}`;

const pinHashCalculado = crypto
  .createHash('sha256')
  .update(base)
  .digest('hex');

if (pinHashCalculado !== motorista.pin_hash) {
  return [{
    json: {
      autorizado: false,
      status_code: 403,
      erro: 'PIN inválido.'
    }
  }];
}

const exigeDispositivoAutorizado = motorista.exige_dispositivo_autorizado === true || motorista.tipo_acesso === 'garagem';
const dispositivo = dispositivosAutorizados.find(d => d.device_id === input.device_id && d.status === 'ativo') || null;

if (exigeDispositivoAutorizado && !dispositivo) {
  return [{
    json: {
      autorizado: false,
      status_code: 403,
      erro: 'Este usuário exige dispositivo autorizado. Use o aparelho da garagem ou solicite liberação ao gestor.',
      device_id: input.device_id
    }
  }];
}

const agora = new Date();
const validoAte = new Date(agora);
const validadeDias = motorista.validade_offline_dias || 30;

validoAte.setDate(validoAte.getDate() + validadeDias);

return [{
  json: {
    autorizado: true,
    status_code: 200,
    motorista_id: motorista.id,
    motorista_matricula: motorista.matricula,
    motorista_nome: motorista.nome,
    unidade: dispositivo?.unidade || motorista.unidade,
    status: motorista.status,
    tipo_acesso: motorista.tipo_acesso || (exigeDispositivoAutorizado ? 'garagem' : 'movel'),
    exige_dispositivo_autorizado: exigeDispositivoAutorizado,
    dispositivo_autorizado: !!dispositivo,
    nome_dispositivo: dispositivo?.nome_dispositivo || 'Dispositivo móvel não cadastrado',
    validado_em: agora.toISOString(),
    valido_offline_ate: validoAte.toISOString(),
    validade_offline_dias: validadeDias
  }
}];

const data = { ...$json };
delete data.foto_base64;
return [{ json: data }];

const foto = $('Preparar Registro').item.json.foto_base64;
const protocolo = $('Preparar Registro').item.json.protocolo || 'checklist';
const base64 = foto.replace(/^data:image\/\w+;base64,/, '');
const buffer = Buffer.from(base64, 'base64');
return [{
  json: { protocolo, directus_id: $json.id },
  binary: {
    foto: await this.helpers.prepareBinaryData(
      buffer,
      `${protocolo}_${Date.now()}.jpg`,
      'image/jpeg'
    )
  }
}];
